sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float beat;
uniform float beatTime;
uniform float beatIndex;
uniform float strength;
uniform float decay;
uniform float beats;
uniform float offset;
uniform float bpm;
uniform float alternate;
uniform float cover;
half4 main(float2 xy) {
    float2 c = size * 0.5;
    float turn = alternate > 0.5 && mod(beatIndex, 2.0) > 0.5 ? -1.0 : 1.0;
    float a = radians(strength) * beat * turn;
    float s = sin(a), k = cos(a);
    float fill = cover > 0.5 ? abs(k) + abs(s) * max(size.x, size.y) / max(min(size.x, size.y), 1.0) : 1.0;
    float2 p = (xy - c) / fill;
    return image.eval(c + float2(k * p.x + s * p.y, k * p.y - s * p.x));
}
